inline void enc_host_allowance(std::string& out, const HostAllowance& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "hosts");
    out += ": ";
    strs(out, v.hosts, depth + 1);
    out += '\n';
    pad(out, depth);
    out += '}';
}

inline void enc_pick_request(std::string& out, const PickRequest& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "model");
    out += ": ";
    esc(out, v.model);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "fresh");
    out += ": ";
    out += v.fresh ? "true" : "false";
    if (v.allowed.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "allowed");
        out += ": ";
        enc_host_allowance(out, *v.allowed, depth + 1);
    }
    if (!v.profile.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "profile");
        out += ": ";
        esc(out, v.profile);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

