    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "up");
    out += ": ";
    out += v.up ? "true" : "false";
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "why");
    out += ": ";
